TLM.f("Tempora/Quad2-3",{"officium":"Feria Quarta infra Hebdomadam II in Quadragesima","rule":["no Gloria","Suffragium=Sanctorum;Vivis;;","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"fallback":"Tempora/Quad2-0","sections":{"Introitus":[{"k":"ref","la":"Ps 37:22-23"},{"k":"text","la":"Ne derelínquas me, Dómine, Deus meus, ne discédas a me: inténde in adjutórium meum, Dómine, virtus salútis meæ."},{"k":"ref","la":"Ps 37:2"},{"k":"text","la":"Dómine, ne in furóre tuo árguas me: neque in ira tua corrípias me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ne derelínquas me, Dómine, Deus meus, ne discédas a me: inténde in adjutórium meum, Dómine, virtus salútis meæ."}],"Oratio":[{"k":"text","la":"Pópulum tuum, quǽsumus, Dómine, propítius réspice: et, quos ab escis carnálibus prǽcipis abstinére, a nóxiis quoque vítiis cessáre concéde."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Esther."},{"k":"ref","la":"Esth 13:8-11; 13:15-17"},{"k":"text","la":"In diébus illis: Orávit Mardochǽus ad Dóminum, dicens: Dómine, Dómine, Rex omnípotens, in dicióne enim tua cuncta sunt pósita, et non est, qui possit tuæ resístere voluntáti, si decréveris salváre Israël. Tu fecísti cœlum et terram, et quidquid cœli ámbitu continétur. Dóminus ómnium es, nec est, qui resístat majestáti tuæ. Et nunc, Dómine Rex, Deus Abraham, miserére pópuli tui, quia volunt nos inimíci nostri pérdere, et hereditátem tuam delére. Ne despícias partem tuam, quam redemísti tibi de Ægýpto. Exáudi deprecatiónem meam, et propítius esto sorti et funículo tuo, et convérte luctum nostrum in gáudium, ut vivéntes laudémus nomen tuum, Dómine, et ne claudas ora te canéntium, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 27:9; 27:1"},{"k":"text","la":"Salvum fac pópulum tuum, Dómine, et bénedic hereditáti tuæ."},{"k":"text","la":"Ad te, Dómine, clamávi: Deus meus, ne síleas a me, et ero símilis descendéntibus in lacum.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 102:10"},{"k":"text","la":"Dómine, non secúndum peccáta nostra, quæ fécimus nos: neque secúndum iniquitátes nostras retríbuas nobis"},{"k":"ref","la":"Ps 78:8-9"},{"k":"text","la":"Dómine, ne memíneris iniquitátum nostrárum antiquárum: cito antícipent nos misericórdiæ tuæ, quia páuperes facti sumus nimis. (Hic genuflectitur)"},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et propter glóriam nóminis tui, Dómine, líbera nos: et propítius esto peccátis nostris, propter nomen tuum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 20:17-28"},{"k":"text","la":"In illo témpore: Ascéndens Jesus Jerosólymam, assúmpsit duódecim discípulos secréto, et ait illis: Ecce, ascéndimus Jerosólymam, et Fílius hóminis tradétur princípibus sacerdótum, et scribis, et condemnábunt eum morte, et tradent eum Géntibus ad illudéndum, et flagellándum, et crucifigéndum, et tértia die resúrget. Tunc accéssit ad eum mater filiórum Zebedǽi cum fíliis suis, adórans et petens áliquid ab eo. Qui dixit ei: Quid vis? Ait illi: Dic, ut sédeant hi duo fílii mei, unus ad déxteram tuam et unus ad sinístram in regno tuo. Respóndens autem Jesus, dixit: Nescítis, quid petátis. Potéstis bíbere cálicem, quem ego bibitúrus sum? Dicunt ei: Póssumus. Ait illis: Cálicem quidem meum bibétis: sedére autem ad déxteram meam vel sinístram, non est meum dare vobis, sed quibus parátum est a Patre meo. Et audiéntes decem, indignáti sunt de duóbus frátribus. Jesus autem vocávit eos ad se, et ait: Scitis, quia príncipes géntium dominántur eórum: et qui majóres sunt, potestátem exércent in eos. Non ita erit inter vos: sed quicúmque volúerit inter vos major fíeri, sit vester miníster: et qui volúerit inter vos primus esse, erit vester servus. Sicut Fílius hóminis non venit ministrári, sed ministráre, et dare ánimam suam, redemptiónem pro multis."}],"Offertorium":[{"k":"ref","la":"Ps 24:1-3"},{"k":"text","la":"Ad te, Dómine, levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur."}],"Secreta":[{"k":"text","la":"Hóstias, Dómine, quas tibi offérimus, propítius réspice: et, per hæc sancta commércia, víncula peccatórum nostrórum absólve."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 10:8"},{"k":"text","la":"Justus Dóminus, et justítiam diléxit: æquitátem vidit vultus ejus."}],"Postcommunio":[{"k":"text","la":"Sumptis, Dómine, sacraméntis: ad redemptiónis ætérnæ, quǽsumus, proficiámus augméntum."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Deus, innocéntiæ restitútor et amátor, dírige ad te tuórum corda servórum: ut, spíritus tui fervóre concépto, et in fide inveniántur stábiles, et in ópere efficáces."},{"k":"macro","name":"Per Dominum"}]},"hr":{"beba466497d54633":{"t":"Ps 37, 22-23; Ps 37, 2\n(Ps 37, 22-23) Nemoj me ostaviti, Gospodine, Bože moj, nemoj se udaljiti od mene. Priteci mi u pomoć, Bože, koji si oslon spasenja mojega. (Ps 37, 2) Gospodine, nemoj me kazniti u gnjevu svojemu, niti me pokarati u srdžbi svojoj.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 37, 22-23) Nemoj me ostaviti, Gospodine, Bože moj, nemoj se udaljiti od mene. Priteci mi u pomoć, Bože, koji si oslon spasenja mojega."},"94c767cb09bbe820":{"t":"<i>Pomolimo se</i>.\nMilostivo pogledaj, Gospodine, svoj narod, i daj da se oni kojima zapovijedaš da se odriču tjelesnih jela odreknu i štetnih mana.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"c7f9ee953cb1747e":{"t":"Est 13, 8-11 i 15-17\nČitanje knjige Esterine. U one dane molio je Mardohej Gospodina: Gospodine, Gospodaru, svemogući Vladaru! Sve je u tvojoj vlasti i nema toga koji bi se mogao oprijeti tvojoj volji, ako odlučiš spasiti Izraela. Stvorio si nebo i zemlju i sve što je pod nebeskim svodom. Gospodar si svemu i nema tko bi se odupro tvojem veličanstvu. A sada, Gospodine, Vladaru, Bože Abrahamov, smiluj se svojem narodu, jer bi nas naši neprijatelji htjeli satrti i tvoju baštinu uništiti. Ne preziri svoga dijela što si ga otkupio za sebe iz Egipta. Usliši moju molitvu i budu milostiv svojem nasljedstvu, obrati našu žalost u radost, da živi slavimo tvoje ime, Gospodine, i ne zatvaraj usta onima koji ti pjevaju, Gospodine, Bože naš."},"203340406f3d2642":{"t":"Ps 27, 9 i 1\nSpasi puk svoj, Gospodine, i blagoslovi svoju baštinu. K tebi, Gospodine, vapijem, ne ogluši se na me, da ne postanem sličan onima koji silaze u grob.\n\nPs 102, 10, Ps 78, 8-9\n(Ps 102, 10) Gospodine, ne uzvrati nam prema našim grijesima koje smo učinili, niti prema našim krivicama. (Ps 78, 8-9) Gospodine, ne sjećaj se naših starih zloća, brzo neka nam dođe ususret tvoje milosrđe, jer postadosmo vrlo bijedni. [Ovdje se poklekne] Pomozi nam, Bože Spasitelju naš, i radi slave svojeg imena izbavi nas, Gospodine. Imaj samilosti s našim grijesima radi imena svojega."},"4cb752d1271f27d1":{"t":"Mt 20, 17-28\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme polazeći Isus u Jeruzalem uze nasamo dvanaest učenika i reče im: Evo, idemo u Jeruzalem i Sina čovječjega će predati svećeničkim poglavarima i književnicima, koji će ga osuditi na smrt i predati nevjernicima, da ga izrugaju, bičuju i razapnu, ali će on treći dan uskrsnuti. Tada pristupi k njemu majka Zebedejevih sinova sa svojim sinovima, pokloni mu se i htjede ga nešto zamoliti. On je upita: Što želiš? Odgovori mu: Odredi da ova moja dva sina sjede jedan s tvoje desne, a drugi s lijeve u tvojem kraljevstvu! A Isus reče: Ne znate što tražite. Možete li piti čašu što ću je ja piti? Odgovore: Možemo! Isus reče: Moju čašu ćete zaista piti. Ali ja ne mogu dati da sjedite meni s desne ili s lijeve vi, nego oni kojima je odredio moj Otac. Kada su to čula ostala desetorica, rasrde se na dva brata. Isus ih dozva k sebi i reče im: Znadete da zemaljski vladari okrutno postupaju s narodom i da velikaši pokazuju moć nad njim. Kod vas neka ne bude tako, nego koji bi među vama htio biti veći, neka vam bude poslužnik. I tko od vas želi biti prvi neka bude vaš sluga. Tako ni Sin čovječji nije došao da mu služe, nego da služi i svoj život dade za otkup mnogih."},"314b0585b7d97b62":{"t":"Ps 24, 1-3\nK tebi, Gospodine, uzdižem svoju dušu, Bože moj, u tebe se uzdam, ne daj da se postidim. Neka mi se ne rugaju neprijatelji, jer se neće smesti nitko od onih koji tebe čekaju."},"4778567304198b58":{"t":"Milostivo pogledaj, Gospodine, darove koje ti prikazujemo i po ovoj svetoj izmjeni odriješi veze naših grijeha.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"dd31b6d0ea68664f":{"t":"Ps 10, 8\nPravedan je Gospodin i ljubi pravdu, njegove oči vide što je pravo."},"1c603e13d455d1b1":{"t":"<i>Pomolimo se</i>.\nPrimivši, Gospodine, sveta otajstva molimo da napredujemo u osiguranju vječnog otkupljenja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"af430d609d2dfbe6":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nBože, koji obnavljaš i ljubiš nevinost, upravljaj k sebi srca svojih slugu da prožeti žarom tvoga duha budu i stalni u vjeri i uspješni u djelovanju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
